// Disassemble and create functions at addresses listed in a seed file.
// Seed file lines: "F <hex>" = create function, "D <hex>" = disassemble only.
// Generated by re/scripts/find_seeds.py.
// @category AstroAssembler

import ghidra.app.cmd.disassemble.DisassembleCommand;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.address.AddressSet;
import ghidra.program.model.listing.Function;

import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.List;

public class SeedFunctions extends GhidraScript {
    @Override
    protected void run() throws Exception {
        String[] args = getScriptArgs();
        if (args.length < 1) {
            printerr("usage: SeedFunctions <seed-file>");
            return;
        }
        List<String> lines = Files.readAllLines(Paths.get(args[0]));
        int disasm = 0, created = 0, existing = 0, failed = 0;
        for (String line : lines) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split("\\s+");
            Address a = toAddr(Long.parseLong(parts[1], 16));
            if (getInstructionAt(a) == null) {
                if (getDataContaining(a) != null && getDataContaining(a).isDefined()) {
                    failed++;
                    continue;
                }
                DisassembleCommand cmd = new DisassembleCommand(a, null, true);
                if (cmd.applyTo(currentProgram, monitor)) disasm++;
            }
            if (!parts[0].equals("F")) continue;
            if (getInstructionAt(a) == null) { failed++; continue; }
            Function f = getFunctionAt(a);
            if (f != null) { existing++; continue; }
            if (createFunction(a, null) != null) created++; else failed++;
        }
        println(String.format("seeds=%d disassembled=%d created=%d existing=%d failed=%d",
                lines.size(), disasm, created, existing, failed));
    }
}
